package com.dy.artisan3d.utilimport androidx.compose.runtime.Composableimport androidx.compose.runtime.SideEffectimport platform.UIKit.*@Composableactual fun PlatformSystemBars(darkTheme: Boolean) {    SideEffect {        val style = if (darkTheme) {            UIStatusBarStyleLightContent // Oq ikonkalar        } else {            UIStatusBarStyleDarkContent  // Qora ikonkalar        }        UIApplication.sharedApplication.setStatusBarStyle(style, animated = true)    }}